window.CITY_SOURCES[272]={"path": "packages/daemon/src/transport/daemon-transport-validation.test.ts", "sources": {"d886953245e98f0c251dc6aa0ee3d217f476bf99": "import { randomUUID } from \"node:crypto\";\nimport { createConnection, createServer, type Server, type Socket } from \"node:net\";\nimport { mkdtempSync, rmSync } from \"node:fs\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\nimport { afterEach, describe, expect, it, vi } from \"vitest\";\nimport { DaemonPolicy } from \"@symnav/daemon\";\nimport { DaemonPolicyTestFactory } from \"../../test/helpers/daemon-policy.js\";\nimport type {\n  DaemonActivitySnapshot,\n  DaemonExecuteRequest,\n  DaemonExecutionServerFrame,\n  DaemonLifecycleRequest,\n} from \"./protocol.js\";\nimport { DAEMON_PROTOCOL_VERSION } from \"./protocol.js\";\nimport { DaemonTransportError } from \"./transport-error.js\";\nimport { TestDaemonTransport as DaemonTransport } from \"../../test/helpers/daemon-transport.js\";\n\ndescribe(\"DaemonTransport validation\", () => {\n  const servers: Server[] = [];\n  const sockets: Socket[] = [];\n  const directories: string[] = [];\n\n  afterEach(async () => {\n    for (const socket of sockets) socket.destroy();\n    sockets.length = 0;\n    await Promise.all(\n      servers.map((server) => new Promise<void>((resolve) => server.close(() => resolve()))),\n    );\n    servers.length = 0;\n    for (const directory of directories) rmSync(directory, { recursive: true, force: true });\n    directories.length = 0;\n  });\n\n  it.each([\n    {\n      kind: \"identify\",\n      instanceId: \"instance\",\n      processToken: \"token\",\n    },\n    pingRequest(),\n  ] satisfies readonly DaemonLifecycleRequest[])(\n    \"uses the status-observer timeout for $kind lifecycle exchanges\",\n    async (request) => {\n      const policy = DaemonPolicyTestFactory.withOverrides(\n        DaemonPolicy.fromSystemMemory({ totalBytes: 1024 ** 3 }),\n        {\n          transport: {\n            singleResponseTimeoutMs: 1_000,\n            statusResponseTimeoutMs: 10,\n          },\n        },\n      );\n      const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n        socket.once(\"data\", () => {\n          setTimeout(\n            () =>\n              socket.end(\n                frame(\n                  request.kind === \"identify\"\n                    ? {\n                        kind: \"identity\",\n                        instanceId: request.instanceId,\n                        processToken: request.processToken,\n                        pid: 123,\n                        startedAt: 10,\n                      }\n                    : {\n                        kind: \"pong\",\n                        protocolVersion: DAEMON_PROTOCOL_VERSION,\n                        instanceId: request.instanceId,\n                        symnavVersion: \"test\",\n                      },\n                ),\n              ),\n            50,\n          );\n        });\n      });\n      const transport = new DaemonTransport({\n        policy,\n        lifecycleResponseTimeoutMs: policy.values.transport.statusResponseTimeoutMs,\n      });\n\n      await expect(transport.request(endpoint, request)).rejects.toMatchObject({\n        code: \"timeout\",\n      });\n    },\n  );\n\n  it(\"uses the ordinary timeout for execution-status exchanges\", async () => {\n    const policy = DaemonPolicyTestFactory.withOverrides(\n      DaemonPolicy.fromSystemMemory({ totalBytes: 1024 ** 3 }),\n      {\n        transport: {\n          singleResponseTimeoutMs: 10,\n          statusResponseTimeoutMs: 1_000,\n        },\n      },\n    );\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.once(\"data\", () => {\n        setTimeout(\n          () =>\n            socket.end(\n              frame({\n                kind: \"execution-status\",\n                instanceId: \"instance\",\n                processToken: \"token\",\n                requestId: \"request\",\n                status: { kind: \"unknown\" },\n              }),\n            ),\n          50,\n        );\n      });\n    });\n    const transport = new DaemonTransport(policy.values);\n\n    await expect(\n      transport.executionStatus(endpoint, {\n        kind: \"execution-status\",\n        protocolVersion: DAEMON_PROTOCOL_VERSION,\n        instanceId: \"instance\",\n        processToken: \"token\",\n        requestId: \"request\",\n      }),\n    ).rejects.toMatchObject({ code: \"timeout\" });\n  });\n\n  it(\"classifies connection refusal before request submission\", async () => {\n    const endpoint = validationEndpoint(directories);\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toMatchObject({\n      name: \"DaemonTransportError\",\n      code: \"unreachable\",\n      delivery: \"not-submitted\",\n    } satisfies Partial<DaemonTransportError>);\n  });\n\n  it(\"classifies lifecycle timeout after request submission\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, () => undefined);\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 10 }).request(endpoint, pingRequest()),\n    ).rejects.toMatchObject({\n      code: \"timeout\",\n      delivery: \"submitted-unconfirmed\",\n    } satisfies Partial<DaemonTransportError>);\n  });\n\n  it(\"classifies admission timeout after request submission\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, () => undefined);\n\n    await expect(\n      new DaemonTransport({ executionRequestTimeoutMs: 10 }).execute(endpoint, executionRequest()),\n    ).rejects.toMatchObject({\n      code: \"timeout\",\n      delivery: \"submitted-unconfirmed\",\n    } satisfies Partial<DaemonTransportError>);\n  });\n\n  it.each([\n    [\"malformed\", invalidResponse(\"malformed\")],\n    [\"truncated\", invalidResponse(\"truncated\")],\n  ] as const)(\"classifies %s response framing as corrupt\", async (_kind, response) => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.end(response);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toMatchObject({\n      code: \"corrupt\",\n      delivery: \"submitted-unconfirmed\",\n    } satisfies Partial<DaemonTransportError>);\n  });\n\n  it.each([\n    [\n      \"instance\",\n      pingRequest(),\n      {\n        kind: \"pong\",\n        protocolVersion: DAEMON_PROTOCOL_VERSION,\n        instanceId: \"other\",\n        symnavVersion: \"test\",\n      },\n    ],\n    [\n      \"token\",\n      {\n        kind: \"identify\",\n        instanceId: \"instance\",\n        processToken: \"expected\",\n      } satisfies DaemonLifecycleRequest,\n      {\n        kind: \"identity\",\n        instanceId: \"instance\",\n        processToken: \"other\",\n        pid: 123,\n        startedAt: 10,\n      },\n    ],\n  ] as const)(\"classifies wrong %s as authentication failure\", async (_kind, request, response) => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.end(frame(response));\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, request),\n    ).rejects.toMatchObject({\n      code: \"authentication\",\n      delivery: \"accepted\",\n    } satisfies Partial<DaemonTransportError>);\n  });\n\n  it(\"classifies a correlated protocol mismatch as authenticated incompatibility\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.end(\n        frame({\n          kind: \"pong\",\n          protocolVersion: DAEMON_PROTOCOL_VERSION + 1,\n          instanceId: \"instance\",\n          symnavVersion: \"test\",\n        }),\n      );\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toMatchObject({\n      code: \"incompatible\",\n      delivery: \"accepted\",\n      authenticatedInstanceId: \"instance\",\n    } satisfies Partial<DaemonTransportError>);\n  });\n\n  it(\"classifies a clean close without a response\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => socket.end());\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toMatchObject({\n      code: \"closed\",\n      delivery: \"submitted-unconfirmed\",\n    } satisfies Partial<DaemonTransportError>);\n  });\n\n  it(\"times out a daemon request that never receives a response\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      setTimeout(() => socket.destroy(), 50);\n    });\n    const transport = new DaemonTransport({ requestTimeoutMs: 10 });\n\n    await expect(transport.request(endpoint, pingRequest())).rejects.toThrow(\n      \"Daemon request timed out\",\n    );\n  });\n\n  it(\"rejects malformed daemon frame JSON\", async () => {\n    const prefix = Buffer.alloc(4);\n    prefix.writeUInt32BE(1);\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(Buffer.concat([prefix, Buffer.from(\"{\")]));\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toThrow(\"malformed JSON\");\n  });\n\n  it(\"rejects oversized inbound daemon frames\", async () => {\n    const prefix = Buffer.alloc(4);\n    prefix.writeUInt32BE(129);\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(prefix);\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ maximumFrameBytes: 128, requestTimeoutMs: 100 }).request(\n        endpoint,\n        pingRequest(),\n      ),\n    ).rejects.toThrow(\"exceeds 128 bytes\");\n  });\n\n  it(\"rejects truncated daemon frames\", async () => {\n    const prefix = Buffer.alloc(4);\n    prefix.writeUInt32BE(10);\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.end(Buffer.concat([prefix, Buffer.from(\"{}\")]));\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toThrow(\"truncated frame\");\n  });\n\n  it(\"rejects unknown daemon response envelopes\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(frame({ kind: \"unknown\" }));\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toThrow(\"Malformed daemon response\");\n  });\n\n  it.each([\n    { transferId: \"transfer\", requestId: \"request\", instanceId: \"instance\", exitCode: 0 },\n    {\n      transferId: \"transfer\",\n      requestId: \"request\",\n      instanceId: \"instance\",\n      exitCode: 0,\n      rawBytes: -1,\n      recordCount: 0,\n      sha256: \"0\".repeat(64),\n    },\n    {\n      transferId: \"transfer\",\n      requestId: \"other\",\n      instanceId: \"instance\",\n      exitCode: 0,\n      rawBytes: 0,\n      recordCount: 0,\n      sha256: \"invalid\",\n    },\n  ])(\"rejects malformed daemon result manifests %#\", async (manifest) => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(\n        Buffer.concat([\n          frame(acceptedFrame()),\n          frame({\n            kind: \"result-manifest\",\n            instanceId: \"instance\",\n            processToken: \"token\",\n            requestId: \"request\",\n            manifest,\n          }),\n        ]),\n      );\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 })\n        .execute(endpoint, executionRequest())\n        .then((receipt) => receipt.completion),\n    ).rejects.toThrow(\"Malformed daemon result manifest\");\n  });\n\n  it(\"rejects a response kind for a different request\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(\n        frame({\n          kind: \"stopped\",\n          instanceId: \"instance\",\n        }),\n      );\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toThrow(\"Daemon pong does not match request protocol and instance\");\n  });\n\n  it(\"rejects multiple daemon responses for one request\", async () => {\n    const response = frame({\n      kind: \"pong\",\n      protocolVersion: DAEMON_PROTOCOL_VERSION,\n      instanceId: \"instance\",\n      symnavVersion: \"test\",\n    });\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(Buffer.concat([response, response]));\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toThrow(\"multiple responses\");\n  });\n\n  it(\"rejects invalid server requests before invoking the handler\", async () => {\n    const endpoint = validationEndpoint(directories);\n    let handled = false;\n    const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n    const listening = await transport.listen(endpoint, async () => {\n      handled = true;\n      return { kind: \"pong\", protocolVersion: 1, instanceId: \"instance\", symnavVersion: \"test\" };\n    });\n    const socket = createConnection(endpoint);\n    await new Promise<void>((resolve, reject) => {\n      socket.once(\"error\", reject);\n      socket.once(\"connect\", () => socket.write(frame({ kind: \"ping\", protocolVersion: \"bad\" })));\n      socket.once(\"close\", () => resolve());\n    });\n\n    expect(handled).toBe(false);\n    await listening.close();\n  });\n\n  it.each([\n    {\n      kind: \"execute\",\n      protocolVersion: DAEMON_PROTOCOL_VERSION,\n      instanceId: \"instance\",\n      processToken: \"token\",\n      requestId: \"/private/source/PaymentProcessor::charge\",\n      request: { argv: [\"refs\", \"symbol\"], cwd: \"/repo\", telemetryEnabled: false },\n    },\n    {\n      kind: \"execution-status\",\n      protocolVersion: DAEMON_PROTOCOL_VERSION,\n      instanceId: \"instance\",\n      processToken: \"token\",\n      requestId: \"/private/source/PaymentProcessor::charge\",\n    },\n    {\n      kind: \"result-fetch\",\n      protocolVersion: DAEMON_PROTOCOL_VERSION,\n      instanceId: \"instance\",\n      processToken: \"token\",\n      requestId: \"/private/source/PaymentProcessor::charge\",\n      offset: 0,\n    },\n    {\n      kind: \"result-ack\",\n      protocolVersion: DAEMON_PROTOCOL_VERSION,\n      instanceId: \"instance\",\n      processToken: \"token\",\n      requestId: \"/private/source/PaymentProcessor::charge\",\n      transferId: \"transfer\",\n    },\n  ] as const)(\n    \"rejects source-shaped $kind request correlation before dispatch\",\n    async (request) => {\n      const endpoint = validationEndpoint(directories);\n      let handled = false;\n      const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n      const listening = await transport.listen(endpoint, async () => {\n        handled = true;\n        return { kind: \"stopped\", instanceId: \"instance\" };\n      });\n      const socket = createConnection(endpoint);\n      await new Promise<void>((resolve, reject) => {\n        socket.once(\"error\", reject);\n        socket.once(\"connect\", () => {\n          socket.write(frame(request));\n          setTimeout(() => {\n            socket.destroy();\n            resolve();\n          }, 20);\n        });\n      });\n\n      expect(handled).toBe(false);\n      await listening.close();\n    },\n  );\n\n  it(\"uses native Windows named pipe endpoints\", () => {\n    expect(validationEndpoint(directories, \"win32\", \"endpoint\")).toBe(\n      \"\\\\\\\\.\\\\pipe\\\\symnav-transport-validation-endpoint\",\n    );\n    expect(directories).toEqual([]);\n  });\n\n  it(\"rejects malformed daemon pong responses\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(\n        frame({\n          kind: \"pong\",\n          protocolVersion: \"invalid\",\n          instanceId: \"instance\",\n          symnavVersion: \"test\",\n        }),\n      );\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toThrow(\"Malformed daemon pong\");\n  });\n\n  it.each([\n    [\"busy without current\", { lifecycle: \"busy\" }],\n    [\n      \"ready with current\",\n      {\n        lifecycle: \"ready\",\n        current: { requestId: \"request\", command: \"refs\", elapsedMs: 1 },\n      },\n    ],\n    [\"recovering without detail\", { lifecycle: \"recovering\" }],\n    [\"ready with recovery detail\", { lifecycle: \"ready\", recoveryDetail: \"resource-pressure\" }],\n    [\n      \"path-shaped current command\",\n      {\n        lifecycle: \"busy\",\n        current: { requestId: \"request\", command: \"/private/source.ts\", elapsedMs: 1 },\n      },\n    ],\n    [\n      \"source-shaped current request\",\n      {\n        lifecycle: \"busy\",\n        current: {\n          requestId: \"/private/source/PaymentProcessor::charge\",\n          command: \"refs\",\n          elapsedMs: 1,\n        },\n      },\n    ],\n    [\"starting with indexed files\", { lifecycle: \"starting\", fileCount: 7 }],\n  ] as const)(\"rejects %s activity snapshots\", async (_label, contradiction) => {\n    const baselineActivity = {\n      lifecycle: \"ready\" as const,\n      pid: 123,\n      startedAt: 10,\n      startupElapsedMs: 20,\n      fileCount: 2,\n      processRssBytes: 100,\n      hardProcessRssBytes: 200,\n      workerGeneration: 1,\n      queued: 0,\n      spoolBytes: 0,\n    } satisfies DaemonActivitySnapshot;\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.end(\n        frame({\n          kind: \"pong\",\n          protocolVersion: DAEMON_PROTOCOL_VERSION,\n          instanceId: \"instance\",\n          symnavVersion: \"test\",\n          activity: {\n            ...baselineActivity,\n            ...contradiction,\n          },\n        }),\n      );\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n    ).rejects.toThrow(\"Malformed daemon pong\");\n  });\n\n  it(\"rejects malformed daemon stop responses\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(frame({ kind: \"stopped\" }));\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, {\n        kind: \"stop\",\n        protocolVersion: DAEMON_PROTOCOL_VERSION,\n        instanceId: \"instance\",\n      }),\n    ).rejects.toThrow(\"Malformed daemon stop response\");\n  });\n\n  it(\"rejects malformed daemon identity responses\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(frame({ kind: \"identity\", instanceId: \"instance\", processToken: \"process\" }));\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, {\n        kind: \"identify\",\n        instanceId: \"instance\",\n        processToken: \"process\",\n      }),\n    ).rejects.toThrow(\"Malformed daemon identity\");\n  });\n\n  it(\"rejects malformed daemon termination responses\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.write(frame({ kind: \"terminating\", instanceId: \"instance\" }));\n      setTimeout(() => socket.destroy(), 50);\n    });\n\n    await expect(\n      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, {\n        kind: \"terminate\",\n        instanceId: \"instance\",\n        processToken: \"process\",\n      }),\n    ).rejects.toThrow(\"Malformed daemon termination response\");\n  });\n\n  it.each([\"startedAt\", \"fileCount\", \"memoryBytes\", \"lastNavigationAt\"] as const)(\n    \"rejects invalid %s pong metadata\",\n    async (field) => {\n      const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n        socket.end(\n          frame({\n            kind: \"pong\",\n            protocolVersion: DAEMON_PROTOCOL_VERSION,\n            instanceId: \"instance\",\n            symnavVersion: \"test\",\n            [field]: \"invalid\",\n          }),\n        );\n      });\n      const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n\n      await expect(transport.request(endpoint, pingRequest())).rejects.toThrow(\n        \"Malformed daemon pong\",\n      );\n    },\n  );\n\n  it(\"rejects nonboolean deferred telemetry requests\", async () => {\n    const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n    const request = {\n      kind: \"execute\",\n      protocolVersion: DAEMON_PROTOCOL_VERSION,\n      instanceId: \"instance\",\n      processToken: \"token\",\n      requestId: \"request\",\n      request: {\n        argv: [\"--version\"],\n        cwd: \"/workspace\",\n        telemetryEnabled: false,\n        deferTelemetry: \"invalid\",\n      },\n    } as unknown as DaemonExecuteRequest;\n\n    expect(() => transport.execute(\"/missing-daemon-endpoint\", request)).toThrow(\n      \"Malformed daemon execution request\",\n    );\n  });\n\n  it(\"rejects an unknown caller-supplied daemon command name\", async () => {\n    const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n    const request = {\n      ...executionRequest(),\n      commandName: \"not-a-command\",\n    } as unknown as DaemonExecuteRequest;\n\n    await expect(\n      Promise.resolve().then(() => transport.execute(\"/missing-daemon-endpoint\", request)),\n    ).rejects.toThrow(\"Malformed daemon execution request\");\n  });\n\n  it(\"rejects legacy embedded completion results\", async () => {\n    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n      socket.end(\n        Buffer.concat([\n          frame(acceptedFrame()),\n          frame({\n            kind: \"completed\",\n            instanceId: \"instance\",\n            processToken: \"token\",\n            requestId: \"request\",\n            result: { exitCode: 0 },\n          }),\n        ]),\n      );\n    });\n    const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n\n    await expect(\n      transport.execute(endpoint, executionRequest()).then((receipt) => receipt.completion),\n    ).rejects.toThrow(\"Malformed daemon response\");\n  });\n});\n\nfunction pingRequest(): DaemonLifecycleRequest {\n  return {\n    kind: \"ping\",\n    protocolVersion: DAEMON_PROTOCOL_VERSION,\n    instanceId: \"instance\",\n  };\n}\n\nfunction executionRequest(): DaemonExecuteRequest {\n  return {\n    kind: \"execute\",\n    protocolVersion: DAEMON_PROTOCOL_VERSION,\n    instanceId: \"instance\",\n    processToken: \"token\",\n    requestId: \"request\",\n    commandName: \"version\",\n    request: {\n      argv: [\"--version\"],\n      cwd: \"/repo\",\n      telemetryEnabled: false,\n      executionMode: \"warm\",\n    },\n  };\n}\n\nfunction acceptedFrame(): DaemonExecutionServerFrame {\n  return {\n    kind: \"accepted\",\n    instanceId: \"instance\",\n    processToken: \"token\",\n    requestId: \"request\",\n    acceptedAt: 1,\n    queuePosition: 0,\n  };\n}\n\nfunction frame(value: unknown): Buffer {\n  const payload = Buffer.from(JSON.stringify(value), \"utf8\");\n  const prefix = Buffer.alloc(4);\n  prefix.writeUInt32BE(payload.length);\n  return Buffer.concat([prefix, payload]);\n}\n\nfunction invalidResponse(scenario: \"malformed\" | \"truncated\"): Buffer {\n  const prefix = Buffer.alloc(4);\n  if (scenario === \"truncated\") {\n    prefix.writeUInt32BE(10);\n    return Buffer.concat([prefix, Buffer.from(\"{}\")]);\n  }\n  prefix.writeUInt32BE(1);\n  return Buffer.concat([prefix, Buffer.from(\"{\")]);\n}\n\nasync function rawServer(\n  servers: Server[],\n  sockets: Socket[],\n  directories: string[],\n  connected: (socket: Socket) => void,\n): Promise<string> {\n  const endpoint = validationEndpoint(directories);\n  const server = createServer((socket) => {\n    sockets.push(socket);\n    connected(socket);\n  });\n  servers.push(server);\n  await new Promise<void>((resolve, reject) => {\n    server.once(\"error\", reject);\n    server.listen(endpoint, resolve);\n  });\n  return endpoint;\n}\n\nfunction validationEndpoint(\n  directories: string[],\n  platform = process.platform,\n  uniqueId: string = randomUUID(),\n): string {\n  if (platform === \"win32\") {\n    return `\\\\\\\\.\\\\pipe\\\\symnav-transport-validation-${uniqueId}`;\n  }\n  const directory = mkdtempSync(join(tmpdir(), \"symnav-transport-validation-\"));\n  directories.push(directory);\n  return join(directory, \"daemon.sock\");\n}\n"}, "diffs": {"26": "diff --git a/packages/daemon/src/transport/daemon-transport-validation.test.ts b/packages/daemon/src/transport/daemon-transport-validation.test.ts\nnew file mode 100644\nindex 000000000..d88695324\n--- /dev/null\n+++ b/packages/daemon/src/transport/daemon-transport-validation.test.ts\n@@ -0,0 +1,765 @@\n+import { randomUUID } from \"node:crypto\";\n+import { createConnection, createServer, type Server, type Socket } from \"node:net\";\n+import { mkdtempSync, rmSync } from \"node:fs\";\n+import { tmpdir } from \"node:os\";\n+import { join } from \"node:path\";\n+import { afterEach, describe, expect, it, vi } from \"vitest\";\n+import { DaemonPolicy } from \"@symnav/daemon\";\n+import { DaemonPolicyTestFactory } from \"../../test/helpers/daemon-policy.js\";\n+import type {\n+  DaemonActivitySnapshot,\n+  DaemonExecuteRequest,\n+  DaemonExecutionServerFrame,\n+  DaemonLifecycleRequest,\n+} from \"./protocol.js\";\n+import { DAEMON_PROTOCOL_VERSION } from \"./protocol.js\";\n+import { DaemonTransportError } from \"./transport-error.js\";\n+import { TestDaemonTransport as DaemonTransport } from \"../../test/helpers/daemon-transport.js\";\n+\n+describe(\"DaemonTransport validation\", () => {\n+  const servers: Server[] = [];\n+  const sockets: Socket[] = [];\n+  const directories: string[] = [];\n+\n+  afterEach(async () => {\n+    for (const socket of sockets) socket.destroy();\n+    sockets.length = 0;\n+    await Promise.all(\n+      servers.map((server) => new Promise<void>((resolve) => server.close(() => resolve()))),\n+    );\n+    servers.length = 0;\n+    for (const directory of directories) rmSync(directory, { recursive: true, force: true });\n+    directories.length = 0;\n+  });\n+\n+  it.each([\n+    {\n+      kind: \"identify\",\n+      instanceId: \"instance\",\n+      processToken: \"token\",\n+    },\n+    pingRequest(),\n+  ] satisfies readonly DaemonLifecycleRequest[])(\n+    \"uses the status-observer timeout for $kind lifecycle exchanges\",\n+    async (request) => {\n+      const policy = DaemonPolicyTestFactory.withOverrides(\n+        DaemonPolicy.fromSystemMemory({ totalBytes: 1024 ** 3 }),\n+        {\n+          transport: {\n+            singleResponseTimeoutMs: 1_000,\n+            statusResponseTimeoutMs: 10,\n+          },\n+        },\n+      );\n+      const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+        socket.once(\"data\", () => {\n+          setTimeout(\n+            () =>\n+              socket.end(\n+                frame(\n+                  request.kind === \"identify\"\n+                    ? {\n+                        kind: \"identity\",\n+                        instanceId: request.instanceId,\n+                        processToken: request.processToken,\n+                        pid: 123,\n+                        startedAt: 10,\n+                      }\n+                    : {\n+                        kind: \"pong\",\n+                        protocolVersion: DAEMON_PROTOCOL_VERSION,\n+                        instanceId: request.instanceId,\n+                        symnavVersion: \"test\",\n+                      },\n+                ),\n+              ),\n+            50,\n+          );\n+        });\n+      });\n+      const transport = new DaemonTransport({\n+        policy,\n+        lifecycleResponseTimeoutMs: policy.values.transport.statusResponseTimeoutMs,\n+      });\n+\n+      await expect(transport.request(endpoint, request)).rejects.toMatchObject({\n+        code: \"timeout\",\n+      });\n+    },\n+  );\n+\n+  it(\"uses the ordinary timeout for execution-status exchanges\", async () => {\n+    const policy = DaemonPolicyTestFactory.withOverrides(\n+      DaemonPolicy.fromSystemMemory({ totalBytes: 1024 ** 3 }),\n+      {\n+        transport: {\n+          singleResponseTimeoutMs: 10,\n+          statusResponseTimeoutMs: 1_000,\n+        },\n+      },\n+    );\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.once(\"data\", () => {\n+        setTimeout(\n+          () =>\n+            socket.end(\n+              frame({\n+                kind: \"execution-status\",\n+                instanceId: \"instance\",\n+                processToken: \"token\",\n+                requestId: \"request\",\n+                status: { kind: \"unknown\" },\n+              }),\n+            ),\n+          50,\n+        );\n+      });\n+    });\n+    const transport = new DaemonTransport(policy.values);\n+\n+    await expect(\n+      transport.executionStatus(endpoint, {\n+        kind: \"execution-status\",\n+        protocolVersion: DAEMON_PROTOCOL_VERSION,\n+        instanceId: \"instance\",\n+        processToken: \"token\",\n+        requestId: \"request\",\n+      }),\n+    ).rejects.toMatchObject({ code: \"timeout\" });\n+  });\n+\n+  it(\"classifies connection refusal before request submission\", async () => {\n+    const endpoint = validationEndpoint(directories);\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toMatchObject({\n+      name: \"DaemonTransportError\",\n+      code: \"unreachable\",\n+      delivery: \"not-submitted\",\n+    } satisfies Partial<DaemonTransportError>);\n+  });\n+\n+  it(\"classifies lifecycle timeout after request submission\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, () => undefined);\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 10 }).request(endpoint, pingRequest()),\n+    ).rejects.toMatchObject({\n+      code: \"timeout\",\n+      delivery: \"submitted-unconfirmed\",\n+    } satisfies Partial<DaemonTransportError>);\n+  });\n+\n+  it(\"classifies admission timeout after request submission\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, () => undefined);\n+\n+    await expect(\n+      new DaemonTransport({ executionRequestTimeoutMs: 10 }).execute(endpoint, executionRequest()),\n+    ).rejects.toMatchObject({\n+      code: \"timeout\",\n+      delivery: \"submitted-unconfirmed\",\n+    } satisfies Partial<DaemonTransportError>);\n+  });\n+\n+  it.each([\n+    [\"malformed\", invalidResponse(\"malformed\")],\n+    [\"truncated\", invalidResponse(\"truncated\")],\n+  ] as const)(\"classifies %s response framing as corrupt\", async (_kind, response) => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.end(response);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toMatchObject({\n+      code: \"corrupt\",\n+      delivery: \"submitted-unconfirmed\",\n+    } satisfies Partial<DaemonTransportError>);\n+  });\n+\n+  it.each([\n+    [\n+      \"instance\",\n+      pingRequest(),\n+      {\n+        kind: \"pong\",\n+        protocolVersion: DAEMON_PROTOCOL_VERSION,\n+        instanceId: \"other\",\n+        symnavVersion: \"test\",\n+      },\n+    ],\n+    [\n+      \"token\",\n+      {\n+        kind: \"identify\",\n+        instanceId: \"instance\",\n+        processToken: \"expected\",\n+      } satisfies DaemonLifecycleRequest,\n+      {\n+        kind: \"identity\",\n+        instanceId: \"instance\",\n+        processToken: \"other\",\n+        pid: 123,\n+        startedAt: 10,\n+      },\n+    ],\n+  ] as const)(\"classifies wrong %s as authentication failure\", async (_kind, request, response) => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.end(frame(response));\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, request),\n+    ).rejects.toMatchObject({\n+      code: \"authentication\",\n+      delivery: \"accepted\",\n+    } satisfies Partial<DaemonTransportError>);\n+  });\n+\n+  it(\"classifies a correlated protocol mismatch as authenticated incompatibility\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.end(\n+        frame({\n+          kind: \"pong\",\n+          protocolVersion: DAEMON_PROTOCOL_VERSION + 1,\n+          instanceId: \"instance\",\n+          symnavVersion: \"test\",\n+        }),\n+      );\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toMatchObject({\n+      code: \"incompatible\",\n+      delivery: \"accepted\",\n+      authenticatedInstanceId: \"instance\",\n+    } satisfies Partial<DaemonTransportError>);\n+  });\n+\n+  it(\"classifies a clean close without a response\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => socket.end());\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toMatchObject({\n+      code: \"closed\",\n+      delivery: \"submitted-unconfirmed\",\n+    } satisfies Partial<DaemonTransportError>);\n+  });\n+\n+  it(\"times out a daemon request that never receives a response\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+    const transport = new DaemonTransport({ requestTimeoutMs: 10 });\n+\n+    await expect(transport.request(endpoint, pingRequest())).rejects.toThrow(\n+      \"Daemon request timed out\",\n+    );\n+  });\n+\n+  it(\"rejects malformed daemon frame JSON\", async () => {\n+    const prefix = Buffer.alloc(4);\n+    prefix.writeUInt32BE(1);\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(Buffer.concat([prefix, Buffer.from(\"{\")]));\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toThrow(\"malformed JSON\");\n+  });\n+\n+  it(\"rejects oversized inbound daemon frames\", async () => {\n+    const prefix = Buffer.alloc(4);\n+    prefix.writeUInt32BE(129);\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(prefix);\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ maximumFrameBytes: 128, requestTimeoutMs: 100 }).request(\n+        endpoint,\n+        pingRequest(),\n+      ),\n+    ).rejects.toThrow(\"exceeds 128 bytes\");\n+  });\n+\n+  it(\"rejects truncated daemon frames\", async () => {\n+    const prefix = Buffer.alloc(4);\n+    prefix.writeUInt32BE(10);\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.end(Buffer.concat([prefix, Buffer.from(\"{}\")]));\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toThrow(\"truncated frame\");\n+  });\n+\n+  it(\"rejects unknown daemon response envelopes\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(frame({ kind: \"unknown\" }));\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toThrow(\"Malformed daemon response\");\n+  });\n+\n+  it.each([\n+    { transferId: \"transfer\", requestId: \"request\", instanceId: \"instance\", exitCode: 0 },\n+    {\n+      transferId: \"transfer\",\n+      requestId: \"request\",\n+      instanceId: \"instance\",\n+      exitCode: 0,\n+      rawBytes: -1,\n+      recordCount: 0,\n+      sha256: \"0\".repeat(64),\n+    },\n+    {\n+      transferId: \"transfer\",\n+      requestId: \"other\",\n+      instanceId: \"instance\",\n+      exitCode: 0,\n+      rawBytes: 0,\n+      recordCount: 0,\n+      sha256: \"invalid\",\n+    },\n+  ])(\"rejects malformed daemon result manifests %#\", async (manifest) => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(\n+        Buffer.concat([\n+          frame(acceptedFrame()),\n+          frame({\n+            kind: \"result-manifest\",\n+            instanceId: \"instance\",\n+            processToken: \"token\",\n+            requestId: \"request\",\n+            manifest,\n+          }),\n+        ]),\n+      );\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 })\n+        .execute(endpoint, executionRequest())\n+        .then((receipt) => receipt.completion),\n+    ).rejects.toThrow(\"Malformed daemon result manifest\");\n+  });\n+\n+  it(\"rejects a response kind for a different request\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(\n+        frame({\n+          kind: \"stopped\",\n+          instanceId: \"instance\",\n+        }),\n+      );\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toThrow(\"Daemon pong does not match request protocol and instance\");\n+  });\n+\n+  it(\"rejects multiple daemon responses for one request\", async () => {\n+    const response = frame({\n+      kind: \"pong\",\n+      protocolVersion: DAEMON_PROTOCOL_VERSION,\n+      instanceId: \"instance\",\n+      symnavVersion: \"test\",\n+    });\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(Buffer.concat([response, response]));\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toThrow(\"multiple responses\");\n+  });\n+\n+  it(\"rejects invalid server requests before invoking the handler\", async () => {\n+    const endpoint = validationEndpoint(directories);\n+    let handled = false;\n+    const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n+    const listening = await transport.listen(endpoint, async () => {\n+      handled = true;\n+      return { kind: \"pong\", protocolVersion: 1, instanceId: \"instance\", symnavVersion: \"test\" };\n+    });\n+    const socket = createConnection(endpoint);\n+    await new Promise<void>((resolve, reject) => {\n+      socket.once(\"error\", reject);\n+      socket.once(\"connect\", () => socket.write(frame({ kind: \"ping\", protocolVersion: \"bad\" })));\n+      socket.once(\"close\", () => resolve());\n+    });\n+\n+    expect(handled).toBe(false);\n+    await listening.close();\n+  });\n+\n+  it.each([\n+    {\n+      kind: \"execute\",\n+      protocolVersion: DAEMON_PROTOCOL_VERSION,\n+      instanceId: \"instance\",\n+      processToken: \"token\",\n+      requestId: \"/private/source/PaymentProcessor::charge\",\n+      request: { argv: [\"refs\", \"symbol\"], cwd: \"/repo\", telemetryEnabled: false },\n+    },\n+    {\n+      kind: \"execution-status\",\n+      protocolVersion: DAEMON_PROTOCOL_VERSION,\n+      instanceId: \"instance\",\n+      processToken: \"token\",\n+      requestId: \"/private/source/PaymentProcessor::charge\",\n+    },\n+    {\n+      kind: \"result-fetch\",\n+      protocolVersion: DAEMON_PROTOCOL_VERSION,\n+      instanceId: \"instance\",\n+      processToken: \"token\",\n+      requestId: \"/private/source/PaymentProcessor::charge\",\n+      offset: 0,\n+    },\n+    {\n+      kind: \"result-ack\",\n+      protocolVersion: DAEMON_PROTOCOL_VERSION,\n+      instanceId: \"instance\",\n+      processToken: \"token\",\n+      requestId: \"/private/source/PaymentProcessor::charge\",\n+      transferId: \"transfer\",\n+    },\n+  ] as const)(\n+    \"rejects source-shaped $kind request correlation before dispatch\",\n+    async (request) => {\n+      const endpoint = validationEndpoint(directories);\n+      let handled = false;\n+      const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n+      const listening = await transport.listen(endpoint, async () => {\n+        handled = true;\n+        return { kind: \"stopped\", instanceId: \"instance\" };\n+      });\n+      const socket = createConnection(endpoint);\n+      await new Promise<void>((resolve, reject) => {\n+        socket.once(\"error\", reject);\n+        socket.once(\"connect\", () => {\n+          socket.write(frame(request));\n+          setTimeout(() => {\n+            socket.destroy();\n+            resolve();\n+          }, 20);\n+        });\n+      });\n+\n+      expect(handled).toBe(false);\n+      await listening.close();\n+    },\n+  );\n+\n+  it(\"uses native Windows named pipe endpoints\", () => {\n+    expect(validationEndpoint(directories, \"win32\", \"endpoint\")).toBe(\n+      \"\\\\\\\\.\\\\pipe\\\\symnav-transport-validation-endpoint\",\n+    );\n+    expect(directories).toEqual([]);\n+  });\n+\n+  it(\"rejects malformed daemon pong responses\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(\n+        frame({\n+          kind: \"pong\",\n+          protocolVersion: \"invalid\",\n+          instanceId: \"instance\",\n+          symnavVersion: \"test\",\n+        }),\n+      );\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toThrow(\"Malformed daemon pong\");\n+  });\n+\n+  it.each([\n+    [\"busy without current\", { lifecycle: \"busy\" }],\n+    [\n+      \"ready with current\",\n+      {\n+        lifecycle: \"ready\",\n+        current: { requestId: \"request\", command: \"refs\", elapsedMs: 1 },\n+      },\n+    ],\n+    [\"recovering without detail\", { lifecycle: \"recovering\" }],\n+    [\"ready with recovery detail\", { lifecycle: \"ready\", recoveryDetail: \"resource-pressure\" }],\n+    [\n+      \"path-shaped current command\",\n+      {\n+        lifecycle: \"busy\",\n+        current: { requestId: \"request\", command: \"/private/source.ts\", elapsedMs: 1 },\n+      },\n+    ],\n+    [\n+      \"source-shaped current request\",\n+      {\n+        lifecycle: \"busy\",\n+        current: {\n+          requestId: \"/private/source/PaymentProcessor::charge\",\n+          command: \"refs\",\n+          elapsedMs: 1,\n+        },\n+      },\n+    ],\n+    [\"starting with indexed files\", { lifecycle: \"starting\", fileCount: 7 }],\n+  ] as const)(\"rejects %s activity snapshots\", async (_label, contradiction) => {\n+    const baselineActivity = {\n+      lifecycle: \"ready\" as const,\n+      pid: 123,\n+      startedAt: 10,\n+      startupElapsedMs: 20,\n+      fileCount: 2,\n+      processRssBytes: 100,\n+      hardProcessRssBytes: 200,\n+      workerGeneration: 1,\n+      queued: 0,\n+      spoolBytes: 0,\n+    } satisfies DaemonActivitySnapshot;\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.end(\n+        frame({\n+          kind: \"pong\",\n+          protocolVersion: DAEMON_PROTOCOL_VERSION,\n+          instanceId: \"instance\",\n+          symnavVersion: \"test\",\n+          activity: {\n+            ...baselineActivity,\n+            ...contradiction,\n+          },\n+        }),\n+      );\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, pingRequest()),\n+    ).rejects.toThrow(\"Malformed daemon pong\");\n+  });\n+\n+  it(\"rejects malformed daemon stop responses\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(frame({ kind: \"stopped\" }));\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, {\n+        kind: \"stop\",\n+        protocolVersion: DAEMON_PROTOCOL_VERSION,\n+        instanceId: \"instance\",\n+      }),\n+    ).rejects.toThrow(\"Malformed daemon stop response\");\n+  });\n+\n+  it(\"rejects malformed daemon identity responses\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(frame({ kind: \"identity\", instanceId: \"instance\", processToken: \"process\" }));\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, {\n+        kind: \"identify\",\n+        instanceId: \"instance\",\n+        processToken: \"process\",\n+      }),\n+    ).rejects.toThrow(\"Malformed daemon identity\");\n+  });\n+\n+  it(\"rejects malformed daemon termination responses\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.write(frame({ kind: \"terminating\", instanceId: \"instance\" }));\n+      setTimeout(() => socket.destroy(), 50);\n+    });\n+\n+    await expect(\n+      new DaemonTransport({ requestTimeoutMs: 100 }).request(endpoint, {\n+        kind: \"terminate\",\n+        instanceId: \"instance\",\n+        processToken: \"process\",\n+      }),\n+    ).rejects.toThrow(\"Malformed daemon termination response\");\n+  });\n+\n+  it.each([\"startedAt\", \"fileCount\", \"memoryBytes\", \"lastNavigationAt\"] as const)(\n+    \"rejects invalid %s pong metadata\",\n+    async (field) => {\n+      const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+        socket.end(\n+          frame({\n+            kind: \"pong\",\n+            protocolVersion: DAEMON_PROTOCOL_VERSION,\n+            instanceId: \"instance\",\n+            symnavVersion: \"test\",\n+            [field]: \"invalid\",\n+          }),\n+        );\n+      });\n+      const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n+\n+      await expect(transport.request(endpoint, pingRequest())).rejects.toThrow(\n+        \"Malformed daemon pong\",\n+      );\n+    },\n+  );\n+\n+  it(\"rejects nonboolean deferred telemetry requests\", async () => {\n+    const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n+    const request = {\n+      kind: \"execute\",\n+      protocolVersion: DAEMON_PROTOCOL_VERSION,\n+      instanceId: \"instance\",\n+      processToken: \"token\",\n+      requestId: \"request\",\n+      request: {\n+        argv: [\"--version\"],\n+        cwd: \"/workspace\",\n+        telemetryEnabled: false,\n+        deferTelemetry: \"invalid\",\n+      },\n+    } as unknown as DaemonExecuteRequest;\n+\n+    expect(() => transport.execute(\"/missing-daemon-endpoint\", request)).toThrow(\n+      \"Malformed daemon execution request\",\n+    );\n+  });\n+\n+  it(\"rejects an unknown caller-supplied daemon command name\", async () => {\n+    const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n+    const request = {\n+      ...executionRequest(),\n+      commandName: \"not-a-command\",\n+    } as unknown as DaemonExecuteRequest;\n+\n+    await expect(\n+      Promise.resolve().then(() => transport.execute(\"/missing-daemon-endpoint\", request)),\n+    ).rejects.toThrow(\"Malformed daemon execution request\");\n+  });\n+\n+  it(\"rejects legacy embedded completion results\", async () => {\n+    const endpoint = await rawServer(servers, sockets, directories, (socket) => {\n+      socket.end(\n+        Buffer.concat([\n+          frame(acceptedFrame()),\n+          frame({\n+            kind: \"completed\",\n+            instanceId: \"instance\",\n+            processToken: \"token\",\n+            requestId: \"request\",\n+            result: { exitCode: 0 },\n+          }),\n+        ]),\n+      );\n+    });\n+    const transport = new DaemonTransport({ requestTimeoutMs: 100 });\n+\n+    await expect(\n+      transport.execute(endpoint, executionRequest()).then((receipt) => receipt.completion),\n+    ).rejects.toThrow(\"Malformed daemon response\");\n+  });\n+});\n+\n+function pingRequest(): DaemonLifecycleRequest {\n+  return {\n+    kind: \"ping\",\n+    protocolVersion: DAEMON_PROTOCOL_VERSION,\n+    instanceId: \"instance\",\n+  };\n+}\n+\n+function executionRequest(): DaemonExecuteRequest {\n+  return {\n+    kind: \"execute\",\n+    protocolVersion: DAEMON_PROTOCOL_VERSION,\n+    instanceId: \"instance\",\n+    processToken: \"token\",\n+    requestId: \"request\",\n+    commandName: \"version\",\n+    request: {\n+      argv: [\"--version\"],\n+      cwd: \"/repo\",\n+      telemetryEnabled: false,\n+      executionMode: \"warm\",\n+    },\n+  };\n+}\n+\n+function acceptedFrame(): DaemonExecutionServerFrame {\n+  return {\n+    kind: \"accepted\",\n+    instanceId: \"instance\",\n+    processToken: \"token\",\n+    requestId: \"request\",\n+    acceptedAt: 1,\n+    queuePosition: 0,\n+  };\n+}\n+\n+function frame(value: unknown): Buffer {\n+  const payload = Buffer.from(JSON.stringify(value), \"utf8\");\n+  const prefix = Buffer.alloc(4);\n+  prefix.writeUInt32BE(payload.length);\n+  return Buffer.concat([prefix, payload]);\n+}\n+\n+function invalidResponse(scenario: \"malformed\" | \"truncated\"): Buffer {\n+  const prefix = Buffer.alloc(4);\n+  if (scenario === \"truncated\") {\n+    prefix.writeUInt32BE(10);\n+    return Buffer.concat([prefix, Buffer.from(\"{}\")]);\n+  }\n+  prefix.writeUInt32BE(1);\n+  return Buffer.concat([prefix, Buffer.from(\"{\")]);\n+}\n+\n+async function rawServer(\n+  servers: Server[],\n+  sockets: Socket[],\n+  directories: string[],\n+  connected: (socket: Socket) => void,\n+): Promise<string> {\n+  const endpoint = validationEndpoint(directories);\n+  const server = createServer((socket) => {\n+    sockets.push(socket);\n+    connected(socket);\n+  });\n+  servers.push(server);\n+  await new Promise<void>((resolve, reject) => {\n+    server.once(\"error\", reject);\n+    server.listen(endpoint, resolve);\n+  });\n+  return endpoint;\n+}\n+\n+function validationEndpoint(\n+  directories: string[],\n+  platform = process.platform,\n+  uniqueId: string = randomUUID(),\n+): string {\n+  if (platform === \"win32\") {\n+    return `\\\\\\\\.\\\\pipe\\\\symnav-transport-validation-${uniqueId}`;\n+  }\n+  const directory = mkdtempSync(join(tmpdir(), \"symnav-transport-validation-\"));\n+  directories.push(directory);\n+  return join(directory, \"daemon.sock\");\n+}\n"}};
